-- =============================================================================
-- OspitiWebServer Ã¢â‚¬â€ Installazione DB completa da zero
-- Destinazione: phpMyAdmin (SiteGround) Ã¢â‚¬â€ database VUOTO gia creato
-- Charset consigliato: utf8mb4 / utf8mb4_0900_ai_ci
--
-- AVVISI:
--   * Selezionare il database di destinazione nella barra in alto di
--     phpMyAdmin PRIMA di importare: questo file NON contiene
--     CREATE DATABASE / USE (il nome DB e' quello di SiteGround).
--   * NON distruttivo: nessun DROP TABLE / TRUNCATE / DELETE.
--     (Le 7 "DROP TABLE IF EXISTS" di db/V0/01 sono state rimosse
--     durante l'assemblaggio.)
--   * Ri-eseguitibile: CREATE TABLE IF NOT EXISTS + INSERT IGNORE +
--     procedure guardate (safe_add_column / safe_add_index / ecc.).
--   * Unica operazione "irreversibile": db/V1/13_guests_cleanup.sql
--     rimuove 10 colonne morte su `guests` (non usate dal codice);
--     safe_drop_column la rende ri-eseguitibile.
--   * Face-check incluso: db/V0/08_app_delta.sql
--     (face_check_status, doc_face_crop_path, face_similarity,
--      door_pin su registration_sessions).
--   * Admin di default: username `admin` Ã¢â‚¬â€ password impostata in fase di
--     generazione di questo file (CAMBIARE SUBITO dopo il primo login).
-- =============================================================================
SET NAMES utf8mb4;

-- =============================================================================
-- db/V0/01_setup_all.sql
-- =============================================================================
-- =============================================================================
-- V0/01_setup_all.sql â€” Schema completo per installazione pulita
-- Allineato a last_version_db.sql (db di produzione)
-- =============================================================================
-- Esegui solo su database nuovi (non Ã¨ idempotente: le tabelle non devono
-- esistere prima dell'esecuzione).
-- Per upgrades incrementali vedere 02_schema_migrations.sql
-- =============================================================================

-- Pulizia tabelle (Ordine inverso rispetto alle dipendenze)
-- -------------------------------------------------------------------------
-- 1. users â€” autenticazione admin (nessuna dipendenza)
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
    id INT NOT NULL AUTO_INCREMENT,
    username VARCHAR(50) NOT NULL,
    password VARCHAR(255) NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY username (username)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- -------------------------------------------------------------------------
-- 2. user_tokens â€” token di sessione admin (FK â†’ users)
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS user_tokens (
    id INT NOT NULL AUTO_INCREMENT,
    user_id INT NOT NULL,
    token VARCHAR(64) NOT NULL,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP NULL DEFAULT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY token (token),
    KEY user_id (user_id),
    CONSTRAINT user_tokens_ibfk_1
        FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- -------------------------------------------------------------------------
-- 3. lk_sessions â€” sessioni di lookup a breve termine (nessuna dipendenza)
--    (in OLD si chiamava `lookup_sessions` â€” rinominata in linea con prod)
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS lk_sessions (
    id INT NOT NULL AUTO_INCREMENT,
    token VARCHAR(64) NOT NULL,
    expires_at DATETIME NOT NULL,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY token (token),
    KEY idx_token_expiry (token, expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- -------------------------------------------------------------------------
-- 4. registration_sessions â€” sessione di registrazione capofamiglia
--    (in prod non ha FK verso guests, quindi non c'Ã¨ ciclo)
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS registration_sessions (
    id INT NOT NULL AUTO_INCREMENT,
    email VARCHAR(150) NOT NULL,
    token VARCHAR(64) NOT NULL,
    guest_count INT NOT NULL DEFAULT 1,
    token_expires_at TIMESTAMP NOT NULL,
    status ENUM('pending','completed','expired') DEFAULT 'pending',
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY token (token)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- -------------------------------------------------------------------------
-- 5. guests â€” ospite (FK â†’ registration_sessions)
--    Nessuna FK verso `member_type` (tabella assente in prod);
--    `member_type_id` resta come campo "libero" che punta a lk_tipo_alloggiato.codice
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS guests (
    id INT NOT NULL AUTO_INCREMENT,
    registration_id INT DEFAULT NULL,
    member_type_id INT UNSIGNED DEFAULT '1' COMMENT 'Riferimento al tipo di membro',
    first_name VARCHAR(100) DEFAULT NULL,
    last_name VARCHAR(100) DEFAULT NULL,
    gender VARCHAR(20) DEFAULT NULL,
    birth_date DATE DEFAULT NULL,
    birth_city_code VARCHAR(20) DEFAULT NULL,
    birth_prov_code VARCHAR(10) DEFAULT NULL,
    birth_state_code VARCHAR(10) DEFAULT NULL,
    citizenship_state_code VARCHAR(10) DEFAULT NULL,
    doc_type VARCHAR(50) DEFAULT NULL,
    doc_number VARCHAR(50) DEFAULT NULL,
    doc_issue_city VARCHAR(100) DEFAULT NULL,
    arrival_date DATE DEFAULT NULL,
    departure_date DATE DEFAULT NULL,
    stay_days INT DEFAULT NULL,
    email VARCHAR(150) NOT NULL,
    origine CHAR(1) DEFAULT 'M',
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    num_persons INT DEFAULT '1',
    PRIMARY KEY (id),
    KEY registration_id (registration_id),
    CONSTRAINT guests_ibfk_1
        FOREIGN KEY (registration_id) REFERENCES registration_sessions (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- -------------------------------------------------------------------------
-- 6. registration_tokens â€” token di registrazione (FK â†’ guests)
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS registration_tokens (
    id INT NOT NULL AUTO_INCREMENT,
    guest_id INT NOT NULL,
    token VARCHAR(64) NOT NULL,
    expires_at DATETIME NOT NULL,
    used_at DATETIME DEFAULT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY token (token),
    KEY guest_id (guest_id),
    CONSTRAINT registration_tokens_ibfk_1
        FOREIGN KEY (guest_id) REFERENCES guests (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- -------------------------------------------------------------------------
-- 7. registrations â€” riga persona nel form (FK â†’ registration_tokens, guests)
--    Nessuna FK verso `member_type`: `member_type_id` resta campo "libero"
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS registrations (
    id INT NOT NULL AUTO_INCREMENT,
    token_id INT NOT NULL,
    guest_id INT NOT NULL,
    person_index INT NOT NULL,
    member_type_id INT UNSIGNED NOT NULL COMMENT 'Riferimento al tipo di membro',
    first_name VARCHAR(255) NOT NULL,
    last_name VARCHAR(255) NOT NULL,
    email VARCHAR(255) DEFAULT NULL,
    phone VARCHAR(50) DEFAULT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    gender VARCHAR(10) DEFAULT NULL,
    birth_date DATE DEFAULT NULL,
    birth_city_code VARCHAR(20) DEFAULT NULL,
    birth_prov_code VARCHAR(20) DEFAULT NULL,
    birth_state_code VARCHAR(20) DEFAULT NULL,
    citizenship_state_code VARCHAR(20) DEFAULT NULL,
    doc_type VARCHAR(50) DEFAULT NULL,
    doc_number VARCHAR(100) DEFAULT NULL,
    doc_issue_city VARCHAR(255) DEFAULT NULL,
    PRIMARY KEY (id),
    KEY token_id (token_id),
    KEY guest_id (guest_id),
    CONSTRAINT registrations_ibfk_1
        FOREIGN KEY (token_id) REFERENCES registration_tokens (id) ON DELETE CASCADE,
    CONSTRAINT registrations_ibfk_2
        FOREIGN KEY (guest_id) REFERENCES guests (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- =============================================================================
-- db/V0/03_seed_data.sql
-- =============================================================================
-- =============================================================================
-- V0/03_seed_data.sql â€” Dati di riferimento (lookup tables)
-- Allineato a last_version_db.sql (db di produzione)
-- =============================================================================
-- Esecuzione indipendente (INSERT IGNORE): le tabelle di lookup qui sotto
-- hanno "CREATE TABLE IF NOT EXISTS" quindi il file Ã¨ autosufficiente.
--
-- Attenzione: lo schema OLD seedava anche `member_type`, che NON esiste in
-- prod e che V0 non crea. Non viene piÃ¹ popolata.
--
-- lk_comuni (11k+ righe) Ã¨ in 04_table_comuni.sql
-- =============================================================================

-- -------------------------------------------------------------------------
-- 1. lk_tipo_alloggiato â€” tipi di alloggio GIES (codici che valorizzano
--    guests.member_type_id / registrations.member_type_id: 16-20)
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS lk_tipo_alloggiato (
    codice VARCHAR(10) PRIMARY KEY,
    descrizione VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

