-- -------------------------------------------------------------------------
-- 2. lk_documenti â€” tipi di documento (codici ufficiali Anagrafe)
--    (seed identico a last_version_db.sql)
-- -------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS lk_documenti (
    codice VARCHAR(10) PRIMARY KEY,
    descrizione VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

