-- 4. lk_comuni â€” comuni italiani (~11k righe)
--    In un file separato per le sue dimensioni.
--    Esecuzione:  mysql -u <user> -p ospiti_db < 04_table_comuni.sql
--

-- =============================================================================
-- db/V0/04_table_comuni.sql
-- =============================================================================
CREATE TABLE IF NOT EXISTS lk_comuni (
    codice VARCHAR(20) PRIMARY KEY,
    descrizione VARCHAR(255) NOT NULL,
    provincia VARCHAR(10),
    data_fine_val DATETIME
);

