-- db/V1/03_ALTER_registrations.sql
-- =============================================================================
-- =============================================================================
-- 03_ALTER_registrations.sql â€” ROSS 1000 (Fase 1, campi 11-14: residenza)
-- =============================================================================
-- Aggiunge le colonne di residenza (per persona) alla tabella `registrations`.
-- Idempotente: safe_add_column verifica esistenza colonna via information_schema
-- (pattern db/OLD/07_face_check_schema.sql). Run ripetibili.
--
-- IMPORTANTE: seleziona il database di destinazione in phpMyAdmin PRIMA di
-- eseguire (ogni ambiente ha un nome DB diverso; qui non si hardcode 'USE').
--
-- Le colonne riutilizzano l'autocomplete lk_comuni giÃ  usato per la nascita
-- (codici comuni/prov). Nessuna FK fisica (valori liberi).
-- =============================================================================

DROP PROCEDURE IF EXISTS safe_add_column;
DELIMITER //
CREATE PROCEDURE safe_add_column(p_table VARCHAR(64), p_column_def TEXT)
BEGIN
    DECLARE col_name VARCHAR(64);
    DECLARE col_count INT;
    SET col_name = REPLACE(SUBSTRING_INDEX(p_column_def, ' ', 1), '`', '');

    SELECT COUNT(*) INTO col_count FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = col_name;

    IF col_count = 0 THEN
        SET @ddl = CONCAT('ALTER TABLE `', p_table, '` ADD COLUMN ', p_column_def);
        PREPARE stmt FROM @ddl;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END //
DELIMITER ;

-- 11 cod. comune residenza (obbl. se stato = Italia)
CALL safe_add_column('registrations', 'res_city_code VARCHAR(20) DEFAULT NULL COMMENT ''ROSS 11 - cod. comune residenza''');

-- 12 prov. residenza (obbl. se stato = Italia)
CALL safe_add_column('registrations', 'res_prov_code VARCHAR(10) DEFAULT NULL COMMENT ''ROSS 12 - prov. residenza''');

-- 13 stato residenza
CALL safe_add_column('registrations', 'res_state_code VARCHAR(10) DEFAULT NULL COMMENT ''ROSS 13 - stato residenza''');

-- 14 indirizzo (opzionale)
CALL safe_add_column('registrations', 'res_address VARCHAR(50) DEFAULT NULL COMMENT ''ROSS 14 - indirizzo residenza''');

DROP PROCEDURE IF EXISTS safe_add_column;

