-- db/V1/04_ALTER_guests.sql
-- =============================================================================
-- =============================================================================
-- 04_ALTER_guests.sql â€” ROSS 1000 (Fase 1, campi 19-20: tipo turismo / mezzo)
-- =============================================================================
-- Aggiunge le colonne di viaggio (per soggiorno) alla tabella `guests`.
-- Idempotente: safe_add_column + safe_add_index verificano esistenza via
-- information_schema (pattern db/OLD/07_face_check_schema.sql). Run ripetibili.
--
-- IMPORTANTE: seleziona il database di destinazione in phpMyAdmin PRIMA di
-- eseguire (ogni ambiente ha un nome DB diverso; qui non si hardcode 'USE').
--
-- `valore` libero conforme a tracciato ROSS: FK logico verso
-- lk_tipo_turismo.valore / lk_mezzo_trasporto.valore (niente vincolo fisico).
-- =============================================================================

DROP PROCEDURE IF EXISTS safe_add_column;
DELIMITER //
CREATE PROCEDURE safe_add_column(p_table VARCHAR(64), p_column_def TEXT)
BEGIN
    DECLARE col_name VARCHAR(64);
    DECLARE col_count INT;
    SET col_name = REPLACE(SUBSTRING_INDEX(p_column_def, ' ', 1), '`', '');

    SELECT COUNT(*) INTO col_count FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = col_name;

    IF col_count = 0 THEN
        SET @ddl = CONCAT('ALTER TABLE `', p_table, '` ADD COLUMN ', p_column_def);
        PREPARE stmt FROM @ddl;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS safe_add_index;
DELIMITER //
CREATE PROCEDURE safe_add_index(p_table VARCHAR(64), p_idx_name VARCHAR(100), p_idx_def TEXT)
BEGIN
    DECLARE idx_count INT;
    SELECT COUNT(*) INTO idx_count FROM information_schema.STATISTICS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND INDEX_NAME = p_idx_name;

    IF idx_count = 0 THEN
        SET @ddl = CONCAT('ALTER TABLE `', p_table, '` ADD ', p_idx_def);
        PREPARE stmt FROM @ddl;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END //
DELIMITER ;

-- 19 Tipo Turismo (per soggiorno, condiviso dal gruppo)
CALL safe_add_column('guests', 'tour_type VARCHAR(60) DEFAULT NULL COMMENT ''ROSS 19 - tipo turismo (lk_tipo_turismo.valore)''');

-- 20 Mezzo Trasporto (per soggiorno, condiviso dal gruppo)
CALL safe_add_column('guests', 'transport_mean VARCHAR(60) DEFAULT NULL COMMENT ''ROSS 20 - mezzo trasporto (lk_mezzo_trasporto.valore)''');

-- Indici (opz.) per filtri export
CALL safe_add_index('guests', 'idx_guests_tour_type', 'KEY `idx_guests_tour_type` (`tour_type`)');
CALL safe_add_index('guests', 'idx_guests_transport_mean', 'KEY `idx_guests_transport_mean` (`transport_mean`)');

DROP PROCEDURE IF EXISTS safe_add_column;
DROP PROCEDURE IF EXISTS safe_add_index;

