-- db/V1/05_ALTER_registration_tokens.sql
-- =============================================================================
-- =============================================================================
-- 05_ALTER_registration_tokens.sql â€” ROSS 1000 (Fase 1.5, token due-step)
-- =============================================================================
-- Aggiunge la colonna `phase1_at` alla tabella `registration_tokens`.
--
-- Semantica (form due step sullo STESSO token):
--     used_at IS NULL  AND  phase1_at IS NULL â†’ Step 1 ancora da fare
--     phase1_at NOT NULL AND used_at IS NULL  â†’ Step 1 fatto, Step 2 aperto
--     used_at NOT NULL                        â†’ completo (entrambi i step chiusi)
--
-- Il Step 1 (POST /api/register/submit) imposta SOLO `phase1_at` (NON `used_at`),
-- cosÃ¬ il token resta valido per il Step 2 (POST /api/register/travel) che a sua
-- volta imposta `used_at` per chiudere il ciclo.
--
-- Idempotente: safe_add_column verifica esistenza colonna via information_schema
-- (pattern db/OLD/07_face_check_schema.sql). Run ripetibili.
--
-- IMPORTANTE: seleziona il database di destinazione in phpMyAdmin PRIMA di
-- eseguire (ogni ambiente ha un nome DB diverso; qui non si hardcode 'USE').
-- =============================================================================

DROP PROCEDURE IF EXISTS safe_add_column;
DELIMITER //
CREATE PROCEDURE safe_add_column(p_table VARCHAR(64), p_column_def TEXT)
BEGIN
    DECLARE col_name VARCHAR(64);
    DECLARE col_count INT;
    SET col_name = REPLACE(SUBSTRING_INDEX(p_column_def, ' ', 1), '`', '');

    SELECT COUNT(*) INTO col_count FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = col_name;

    IF col_count = 0 THEN
        SET @ddl = CONCAT('ALTER TABLE `', p_table, '` ADD COLUMN ', p_column_def);
        PREPARE stmt FROM @ddl;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END //
DELIMITER ;

-- Fattura temporale del completamento dello Step 1 (dati persona + residenza)
CALL safe_add_column('registration_tokens', 'phase1_at DATETIME DEFAULT NULL COMMENT ''ROSS 1000 - Step 1 completato a (null = Step 1 non ancora fatto)''');

DROP PROCEDURE IF EXISTS safe_add_column;

