--
-- Posizione: su `guests` per coerenza con il PHP esistente
--     â€¢ FaceCheckService::setAccessCode()  â†’ UPDATE guests SET access_code = ?
--     â€¢ FaceCheckService::verifyFace()     â†’ SELECT g.access_code ...
-- (db/OLD/07_face_check_schema.sql lo metteva su registration_sessions: qui si
--  uniforma su `guests`, che Ã¨ la tabella effettivamente letta/scritta dal codice).
