-- =============================================================================
-- db/V1/07_selfcheckin.sql
-- =============================================================================
-- =============================================================================
-- 07_selfcheckin.sql â€” Self check-in con approvazione manuale dell'host
-- =============================================================================
-- FunzionalitÃ :
--   â€¢ Introduce il campo `purpose` su `registration_tokens` per separare i
--     token del form di registrazione (purpose='form') dai token di self
--     check-in (purpose='selfcheckin'). Un token `form` NON apre il flusso
--     self check-in e viceversa (spec Â§10.1).
--   â€¢ Crea la tabella `selfcheckin_sessions`: una riga per tentativo di
--     verifica (macchina a stati in_attesa â†’ richiesta â†’ verificato /
--     rifiutato, piÃ¹ revocato/scaduto).
--
-- Privacy (spec Â§2): NESSUNA colonna per immagini, video, punteggi o dati
-- del documento. Il riconoscimento Ã¨ fatto da una persona (de visu a
-- distanza) e il software si limita a registrare: stato, timestamp, utente
-- che decide, nota breve facoltativa e codice di sfida temporaneo.
--
-- Idempotente: `safe_add_column` (pattern db/V1/05 e db/V1/06) +
-- CREATE TABLE IF NOT EXISTS + check indice su information_schema. Run
-- ripetibili senza errori.
--
-- IMPORTANTE: seleziona il database di destinazione in phpMyAdmin PRIMA di
-- eseguire (ogni ambiente ha un nome DB diverso; qui non si hardcode 'USE').
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 1. Colonna `purpose` su registration_tokens (default 'form' â†’ le righe
--    esistenti restano token del form di registrazione)
-- ---------------------------------------------------------------------------
DROP PROCEDURE IF EXISTS safe_add_column;
DELIMITER //
CREATE PROCEDURE safe_add_column(p_table VARCHAR(64), p_column_def TEXT)
BEGIN
    DECLARE col_name VARCHAR(64);
    DECLARE col_count INT;

    SET col_name = REPLACE(SUBSTRING_INDEX(p_column_def, ' ', 1), '`', '');
    SELECT COUNT(*) INTO col_count FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = col_name;

    IF col_count = 0 THEN
        SET @ddl = CONCAT('ALTER TABLE `', p_table, '` ADD COLUMN ', p_column_def);
        PREPARE stmt FROM @ddl;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END //
DELIMITER ;

CALL safe_add_column('registration_tokens', 'purpose ENUM(''form'',''selfcheckin'') NOT NULL DEFAULT ''form'' COMMENT ''Scopo del token: form di registrazione o self check-in''');

DROP PROCEDURE IF EXISTS safe_add_column;

-- Indire `purpose` (solo se l'indice non esiste giÃ )
SET @idx_count = (
    SELECT COUNT(*) FROM information_schema.STATISTICS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME   = 'registration_tokens'
      AND INDEX_NAME   = 'idx_purpose'
);
SET @ddl = IF(@idx_count = 0,
              'CREATE INDEX idx_purpose ON registration_tokens(purpose)',
              'SELECT 1');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;



-- =============================================================================
-- db/V1/08_availability_blocks.sql
-- =============================================================================
-- =============================================================================
-- 08_availability_blocks.sql â€” API DisponibilitÃ  (spec api-disponibilita-spec-v2.md)
-- =============================================================================
-- Tabella dei BLOCCHI MANUALI di disponibilitÃ : notti occupate ma NON
-- provenienti da una prenotazione reale (manutenzione, vendita WhatsApp
-- non-tracciata in ICS, chiusura stagionale). La disponibilitÃ  pubblica Ã¨
-- l'UNION di `guests` (confermati/importati) + questa tabella (spec Â§5.3).
--
-- Nota naming: il campo `reason` (non `motivazione`) Ã¨ scelto per coerenza col
-- resto dello schema (comment `purpose`, `phase1_at`, ecc.): il campo Ã¨ solo
-- un'etichetta testuale opzionale per l'owner.
--
-- Semantica intervallo [in, out): `in` = giorno di ARRIVO del blocco,
-- `out` = giorno di PARTENZA (notte ESCLUSA). `out` occupa le notti
-- `in â€¦ out-1`. La validazione `in < out` Ã¨ fatta in PHP (AddBlock), non in DB.
--
-- `created_by` = INT, coerente con `users.id` (init.sql). FK ON DELETE SET NULL
-- (il blocco resta anche se l'admin viene rimosso).
--
-- Idempotente: CREATE TABLE IF NOT EXISTS + check esistenza della FK via
-- information_schema (pattern db/V1/07). Run ripetibili senza errori.
--
-- IMPORTANTE: seleziona il database di destinazione in phpMyAdmin PRIMA di
-- eseguire (ogni ambiente ha un nome DB diverso; qui non si hardcode 'USE').
-- `in` / `out` sono PAROLE RISERVATE MySQL â†’ vanno backtickate in ogni query.
-- =============================================================================

CREATE TABLE IF NOT EXISTS availability_blocks (
    `id`          INT           AUTO_INCREMENT PRIMARY KEY,
    `in`          DATE          NOT NULL COMMENT 'Giorno di ARRIVO del blocco (notte inclusa)',
    `out`         DATE          NOT NULL COMMENT 'Giorno di PARTENZA del blocco (notte ESCLUSA)',
    `reason`      VARCHAR(120)  NULL  COMMENT 'Descrizione opzionale (motivazione/testuale)',
    `created_by`  INT           NULL  COMMENT 'FK logico â†’ users.id (admin che lo ha creato)',
    `created_at`  TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_blocks_user FOREIGN KEY (`created_by`) REFERENCES `users`(`id`) ON DELETE SET NULL,
    KEY idx_blocks_year (`in`, `out`)
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci
  COMMENT='API DisponibilitÃ : blocchi manuali di notti (non-OTA)';

-- UNIQUE su (in, out) per idempotenza / deduplication (non per ordine).
-- Verificato via information_schema per idempotenza (run ripetibili).
SET @uq_count = (
    SELECT COUNT(*) FROM information_schema.STATISTICS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME   = 'availability_blocks'
      AND INDEX_NAME   = 'uq_blocks'
);
SET @ddl = IF(@uq_count = 0,
              'ALTER TABLE availability_blocks ADD CONSTRAINT uq_blocks UNIQUE (`in`, `out`)',
              'SELECT 1');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- =============================================================================
-- db/V1/09_guests_stato.sql
-- =============================================================================
-- =============================================================================
-- 09_guests_stato.sql â€” Colonna di stato generica su `guests`
-- =============================================================================
-- Colonna `stato CHAR(1)` riutilizzabile per diverse segnalazioni sul guest.
-- Il significato del carattere Ã¨ definito da un DIZIONARIO (non da ENUM, cosÃ¬
-- si potrÃ  aggiungere un nuovo codice senza toccare lo schema):
--
--   NULL = nessuna anomalia
--   'I'  = errore import ICS: il periodo (arrival, departure) non compare piÃ¹
--          nella ICS corrente di Airbnb, ma il guest ha â‰¥ 1 token in
--          registration_tokens (link inviato/completato/scaduto, o selfcheckin).
--          Il record Ã¨ preservato dalla delete dello sync e va segnalato all'host.
--
-- Riferimenti: plans/2026-10-08-import-ics.md, src/GuestManager.php
-- (deleteImportedGuests, refreshImportAnomalies),
-- public/index.php (POST /api/import-ics, GET /api/guests).
--
-- Idempotente: `safe_add_column` (pattern db/V1/07 e db/V1/05). Run ripetibili
-- senza errori.
--
-- IMPORTANTE: seleziona il database di destinazione in phpMyAdmin PRIMA di
-- eseguire (ogni ambiente ha un nome DB diverso; qui non si hardcode 'USE').
-- =============================================================================

DROP PROCEDURE IF EXISTS safe_add_column;
DELIMITER //
CREATE PROCEDURE safe_add_column(p_table VARCHAR(64), p_column_def TEXT)
BEGIN
    DECLARE col_name VARCHAR(64);
    DECLARE col_count INT;

    SET col_name = REPLACE(SUBSTRING_INDEX(p_column_def, ' ', 1), '`', '');
    SELECT COUNT(*) INTO col_count FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = col_name;

    IF col_count = 0 THEN
        SET @ddl = CONCAT('ALTER TABLE `', p_table, '` ADD COLUMN ', p_column_def);
        PREPARE stmt FROM @ddl;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END //
DELIMITER ;

CALL safe_add_column('guests', 'stato CHAR(1) NULL DEFAULT NULL COMMENT ''Dizionario segnalazioni: NULL=nessuna, I=errore import ICS (periodo non piÃ¹ in ICS con token esistente)''');

DROP PROCEDURE IF EXISTS safe_add_column;

-- =============================================================================
-- db/V1/11_guests_deleted.sql
-- =============================================================================
-- =============================================================================
-- 11_guests_deleted.sql â€” Soft delete su `guests`
-- =============================================================================
-- L'host puo eliminare una scheda guest (tasto rosso in guest-form).
-- Invece di cancellare fisicamente (e i dati collegati), la riga viene
-- "nascosta": `deleted_at` viene impostato e `deleted_by` registra chi.
--
--   deleted_at NULL    = guest attivo
--   deleted_at NOTNULL = guest eliminato (niente SELECT lo vede piu, ma il
--                        record resta in archivio con registrations, tokens,
--                        tassa_soggiorno_incassi, selfcheckin_sessions intatti)
--   deleted_by         = FK logico -> users.id (host che ha eliminato)
--
-- Le query "calde" sul list filtrano `deleted_at IS NULL` (vedi
-- src/GuestManager.php). Le tabelle collegate NON vengono toccate: nessuna
-- azione sui FK reali (registrations / registration_tokens) perche qui non si
-- rimuove la riga.
--
-- Riferimenti: plans/soft_delete_guest.md, src/GuestManager.php::softDelete,
-- public/index.php (DELETE /guests/{id} admin).
--
-- Idempotente: `safe_add_column` (pattern db/V1/07 e db/V1/09). Run
-- ripetibili senza errori. L'indice `idx_deleted_at` viene creato solo se
-- assente (MySQL 5.7 non supporta functional/partial index: usiamo un
-- semplice indice sull'unica colonna, sufficiente per il filtro IS NULL).
--
-- NOTA QUOTING: i commenti delle colonne passati a safe_add_column NON devono
-- contenere apostrofi: la stringa attraversa due livelli di quoting (CALL +
-- ALTER TABLE dinamico) e un apostrofo chiude il COMMENT in anticipo (#1064).
--
-- IMPORTANTE: seleziona il database di destinazione in phpMyAdmin PRIMA di
-- eseguire (ogni ambiente ha un nome DB diverso; qui non si hardcode 'USE').
-- =============================================================================

DROP PROCEDURE IF EXISTS safe_add_column;
DELIMITER //
CREATE PROCEDURE safe_add_column(p_table VARCHAR(64), p_column_def TEXT)
BEGIN
    DECLARE col_name VARCHAR(64);
    DECLARE col_count INT;

    SET col_name = REPLACE(SUBSTRING_INDEX(p_column_def, ' ', 1), '`', '');
    SELECT COUNT(*) INTO col_count FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = col_name;

    IF col_count = 0 THEN
        SET @ddl = CONCAT('ALTER TABLE `', p_table, '` ADD COLUMN ', p_column_def);
        PREPARE stmt FROM @ddl;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END //
DELIMITER ;

CALL safe_add_column('guests', 'deleted_at DATETIME NULL DEFAULT NULL COMMENT ''Soft delete: data di rimozione della scheda guest da parte dell host (NULL = attivo)''');
CALL safe_add_column('guests', 'deleted_by INT NULL DEFAULT NULL COMMENT ''FK logico -> users.id (host che ha eliminato)''');

-- Indice per la query calda `WHERE deleted_at IS NULL` (list + dettaglio).
SET @idx_count = (
    SELECT COUNT(*) FROM information_schema.STATISTICS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'guests'
      AND INDEX_NAME = 'idx_deleted_at'
);
SET @ddl = IF(@idx_count = 0,
              'CREATE INDEX idx_deleted_at ON guests(deleted_at)',
              'SELECT 1');
PREPARE idx_stmt FROM @ddl;
EXECUTE idx_stmt;
DEALLOCATE PREPARE idx_stmt;

-- =============================================================================
-- db/V1/12_rooms.sql
-- =============================================================================
-- =============================================================================
-- 12_rooms.sql â€” Modello multi-camera (Fase 3, Passo A)
-- =============================================================================
-- room_types + rooms + seed (1 camera, 1 letto matrimoniale = capacity 2, beds 1).
-- Idempotente: CREATE TABLE IF NOT EXISTS + INSERT IGNORE (run ripetibili).
-- IMPORTANTE: seleziona il database di destinazione in phpMyAdmin PRIMA di eseguire.
-- =============================================================================

CREATE TABLE IF NOT EXISTS room_types (
    id           INT           NOT NULL AUTO_INCREMENT PRIMARY KEY,
    code         VARCHAR(20)   NOT NULL COMMENT 'Codice piano tariffario camera (es. STD)',
    name         VARCHAR(100)  NOT NULL COMMENT 'Nome display',
    capacity     INT           NOT NULL DEFAULT 1
                 COMMENT 'POSTI LETTO (matrimoniale=2) â€” pricing / rate_rules',
    beds_default INT           NOT NULL DEFAULT 1
                 COMMENT 'LETTI FISIici standard per questa tipologia (matrimoniale=1)',
    active       TINYINT(1)    NOT NULL DEFAULT 1,
    UNIQUE KEY uq_rt_code (code)
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci
  COMMENT='Tipologie camera (1 camera per ora; estendibile)';

CREATE TABLE IF NOT EXISTS rooms (
    id           INT           NOT NULL AUTO_INCREMENT PRIMARY KEY,
    room_type_id INT           NOT NULL,
    label        VARCHAR(100)  NOT NULL COMMENT 'Etichetta della camera (es. Cam 1)',
    beds         INT           NOT NULL DEFAULT 1
                 COMMENT 'LETTI FISIici di questa camera (matrimoniale = 1)',
    active       TINYINT(1)    NOT NULL DEFAULT 1,
    UNIQUE KEY uq_room (room_type_id, label),
    CONSTRAINT rooms_ibfk_type FOREIGN KEY (room_type_id) REFERENCES room_types(id)
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci
  COMMENT='Camere fisiche assegnabili';

-- Seed: 1 camera, 1 letto matrimoniale (2 posti), letto fisico = 1
INSERT IGNORE INTO room_types (code, name, capacity, beds_default)
VALUES ('STD', 'Camera', 2, 1);

SET @rt_std = (SELECT id FROM room_types WHERE code = 'STD' LIMIT 1);
INSERT IGNORE INTO rooms (room_type_id, label, beds)
VALUES (@rt_std, 'Cam 1', 1);

-- =============================================================================
-- db/V1/13_guests_cleanup.sql
-- =============================================================================
-- =============================================================================
-- 13_guests_cleanup.sql â€” (Fase 3, Passo B)
-- =============================================================================
-- 1) Prerequisito: eseguire prima 12_rooms.sql (room_types + rooms).
-- 2) guests.room_id INT NOT NULL DEFAULT 1 (FK â†’ rooms(id)).
-- 3) DROP 10 colonne morto su guests (tutte NULL nel dump).
-- 4) Backfill stay_days IS NULL (1 riga oggi, id=29 Â«Pia RichardtÂ»).
-- Idempotente: procedure safe_add_column / safe_add_constraint / safe_drop_column,
-- verifica esistenza via information_schema. Run ripetibili.
-- IMPORTANTE: seleziona il database di destinazione in phpMyAdmin PRIMA di eseguire.
-- =============================================================================

DROP PROCEDURE IF EXISTS safe_add_column;
DELIMITER //
CREATE PROCEDURE safe_add_column(p_table VARCHAR(64), p_column_def TEXT)
BEGIN
    DECLARE col_name VARCHAR(64);
    DECLARE col_count INT;
    SET col_name = REPLACE(SUBSTRING_INDEX(p_column_def, ' ', 1), '`', '');
    SELECT COUNT(*) INTO col_count FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = col_name;
    IF col_count = 0 THEN
        SET @ddl = CONCAT('ALTER TABLE `', p_table, '` ADD COLUMN ', p_column_def);
        PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;
    END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS safe_add_constraint;
DELIMITER //
CREATE PROCEDURE safe_add_constraint(p_table VARCHAR(64), p_con_name VARCHAR(100), p_def TEXT)
BEGIN
    DECLARE con_count INT;
    SELECT COUNT(*) INTO con_count FROM information_schema.TABLE_CONSTRAINTS
      WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND CONSTRAINT_NAME = p_con_name;
    IF con_count = 0 THEN
        SET @ddl = CONCAT('ALTER TABLE `', p_table, '` ADD CONSTRAINT ', p_con_name, ' ', p_def);
        PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;
    END IF;
END //
DELIMITER ;

DROP PROCEDURE IF EXISTS safe_drop_column;
DELIMITER //
CREATE PROCEDURE safe_drop_column(p_table VARCHAR(64), p_column VARCHAR(64))
BEGIN
    DECLARE col_count INT;
    SELECT COUNT(*) INTO col_count FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND COLUMN_NAME = p_column;
    IF col_count > 0 THEN
        SET @ddl = CONCAT('ALTER TABLE `', p_table, '` DROP COLUMN `', p_column, '`');
        PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;
    END IF;
END //
DELIMITER ;

-- 2) room_id (dopo member_type_id)
CALL safe_add_column('guests', 'room_id INT NOT NULL DEFAULT 1 COMMENT ''Camera del soggiorno'' AFTER `member_type_id`');
CALL safe_add_constraint('guests', 'guests_ibfk_room', 'FOREIGN KEY (room_id) REFERENCES rooms(id)');

-- 3) DROP le 10 colonna morte
CALL safe_drop_column('guests', 'gender');
CALL safe_drop_column('guests', 'birth_date');
CALL safe_drop_column('guests', 'birth_city_code');
CALL safe_drop_column('guests', 'birth_prov_code');
CALL safe_drop_column('guests', 'birth_state_code');
CALL safe_drop_column('guests', 'citizenship_state_code');
CALL safe_drop_column('guests', 'doc_type');
CALL safe_drop_column('guests', 'doc_number');
CALL safe_drop_column('guests', 'doc_issue_city');
CALL safe_drop_column('guests', 'num_persons');

-- 4) Backfill stay_days righe NULL (id=29 oggi)
UPDATE guests
   SET stay_days = DATEDIFF(departure_date, arrival_date)
 WHERE stay_days IS NULL
   AND arrival_date IS NOT NULL
   AND departure_date IS NOT NULL;

DROP PROCEDURE IF EXISTS safe_add_column;
DROP PROCEDURE IF EXISTS safe_add_constraint;
DROP PROCEDURE IF EXISTS safe_drop_column;

-- =============================================================================
-- V10 — Fix `guests.id` senza AUTO_INCREMENT.
--
-- La PK di `guests` era `id INT NOT NULL` senza default/auto-increment, mentre
-- GuestManager\createGuest() inserisce senza passare `id` e poi legge
-- lastInsertId(). Inserimento → "Field 'id' doesn't have a default value".
-- Rende AUTO_INCREMENT la colonna, in modo idempotente (no-op se già presente).
-- =============================================================================
SET @ai = (
    SELECT COUNT(*) FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME   = 'guests'
      AND COLUMN_NAME  = 'id'
      AND EXTRA LIKE '%auto_increment%'
);
SET @ddl = IF(@ai = 0,
              'ALTER TABLE guests MODIFY COLUMN id INT NOT NULL AUTO_INCREMENT',
              'SELECT 1');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- =============================================================================
-- V11 - CSRF tokens + rate limiting (tabelle di sicurezza).
--
-- `csrf_tokens`: token CSRF una-tantum per l'invio dei form di registrazione
--   (Step 1 / Step 2). `lookup_token` lega il CSRF al cookie lookup_session
--   (SameSite=Strict); `used_at` rende il token riusabile solo una volta.
-- `rate_limits`: contatori per finestra fissa (action, key) per il rate
--   limiting di login/registrazione (vedi src/RateLimiter.php).
-- =============================================================================
CREATE TABLE IF NOT EXISTS csrf_tokens (
    id INT NOT NULL AUTO_INCREMENT,
    csrf VARCHAR(64) NOT NULL,
    lookup_token VARCHAR(64) DEFAULT NULL,
    used_at DATETIME DEFAULT NULL,
    expires_at DATETIME NOT NULL,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY csrf (csrf),
    KEY idx_csrf_lookup (lookup_token),
    KEY idx_csrf_state (used_at, expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS rate_limits (
    id INT NOT NULL AUTO_INCREMENT,
    action VARCHAR(40) NOT NULL,
    `key` VARCHAR(191) NOT NULL,
    first_hit_at INT NOT NULL,
    counter INT NOT NULL DEFAULT 1,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY action_key (action, `key`),
    KEY idx_rate_key (action, first_hit_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
